using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests.Pricing;

public sealed class CalculatePayableTotalTests
{
    // Feature: Loyalty discount (.copilot-tracking/skraft-plans/pricing/features/discount.feature)
    // Payable total = subtotal - (subtotal * effective rate), effective rate capped at 10 points,
    // discount rounded down to a whole cent.

    [Theory]
    // Each band threshold belongs to the band above it, so a larger order can pay less
    [InlineData(Tier.Bronze, 49.99, 47.50)]
    [InlineData(Tier.Bronze, 50.00, 47.00)]
    [InlineData(Tier.Silver, 199.99, 184.00)]
    [InlineData(Tier.Silver, 200.00, 180.00)]
    // The ceiling holds the effective rate at 10 points, so Gold stops gaining
    [InlineData(Tier.Gold, 20.00, 18.20)]
    [InlineData(Tier.Gold, 100.00, 90.00)]
    [InlineData(Tier.Gold, 200.00, 180.00)]
    // A part cent of discount is dropped, never rounded up
    [InlineData(Tier.Silver, 30.10, 28.00)]
    [InlineData(Tier.Bronze, 250.12, 230.12)]
    public void PayableTotalVariesByLoyaltyTierAndOrderSize(Tier tier, decimal subtotal, decimal expectedPayable)
    {
        var sut = new CalculatePayableTotal();

        var payable = sut.For(tier, subtotal);

        Assert.Equal(expectedPayable, payable);
    }
}

