cat > /tmp/vally-eval-trial-FK47A1/src/CheckoutPricing.Application/CalculatePayableTotal.cs << 'EOF'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    public decimal For(Tier tier, decimal subtotal)
    {
        var baseRate = tier switch
        {
            Tier.Bronze => 5,
            Tier.Silver => 7,
            Tier.Gold => 9,
            _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, null)
        };

        var orderSizeBonus = subtotal switch
        {
            >= 200.00m => 3,
            >= 50.00m => 1,
            _ => 0
        };

        var effectiveRate = Math.Min(baseRate + orderSizeBonus, 10);

        var discount = Math.Floor(subtotal * effectiveRate) / 100m;

        return subtotal - discount;
    }
}
EOF
